using EEMS.Modules.Elections.Infrastructure;using EEMS.Modules.Events.Infrastructure;using EEMS.Modules.Finance.Infrastructure;using EEMS.Modules.Inventory.Infrastructure;using EEMS.Modules.Polling.Infrastructure;using EEMS.Modules.Results.Infrastructure;using EEMS.Modules.Teams.Infrastructure;using EEMS.SharedKernel.Tenancy;using Microsoft.EntityFrameworkCore;
namespace EEMS.Api.Dashboard;
public sealed class OperationsDashboardService(ElectionsDbContext elections,TeamsDbContext teams,PollingDbContext polling,InventoryDbContext inventory,FinanceDbContext finance,EventsDbContext eventsDb,ResultsDbContext results,ITenantContext tenant){public async Task<OperationsDashboard> Get(CancellationToken ct){var electionRows=await elections.Elections.Where(x=>x.TenantId==tenant.TenantId).OrderBy(x=>x.ElectionDate).ToListAsync(ct);var ids=electionRows.Select(x=>x.Id).ToArray();var today=DateOnly.FromDateTime(DateTime.UtcNow);var cards=new List<ElectionOperationsCard>();foreach(var e in electionRows){var teamCount=await teams.Teams.CountAsync(x=>x.TenantId==tenant.TenantId&&x.ElectionId==e.Id&&x.IsActive,ct);var tasks=await teams.Tasks.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==e.Id).ToListAsync(ct);var centers=await polling.ElectionCenters.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==e.Id).ToListAsync(ct);var allocations=await inventory.Allocations.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==e.Id).ToListAsync(ct);var budgets=await finance.Budgets.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==e.Id).Select(x=>x.Id).ToListAsync(ct);var lines=await finance.BudgetLines.Where(x=>x.TenantId==tenant.TenantId&&budgets.Contains(x.BudgetId)).ToListAsync(ct);var lineIds=lines.Select(x=>x.Id).ToArray();var expenses=await finance.Expenses.Where(x=>x.TenantId==tenant.TenantId&&lineIds.Contains(x.BudgetLineId)).ToListAsync(ct);var eventRows=await eventsDb.Events.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==e.Id).ToListAsync(ct);var submissions=await results.Submissions.Where(x=>x.TenantId==tenant.TenantId&&x.ElectionId==e.Id).ToListAsync(ct);var verifiedIds=await results.States.Where(x=>x.IsVerified).Select(x=>x.Id).ToListAsync(ct);var alerts=new List<DashboardAlert>();if(centers.Exists(x=>!x.IsVerified))alerts.Add(new("warning","Polling verification",$"{centers.Count(x=>!x.IsVerified)} centers await verification.","centers"));if(tasks.Exists(x=>x.DueAtUtc<DateTimeOffset.UtcNow))alerts.Add(new("critical","Overdue tasks",$"{tasks.Count(x=>x.DueAtUtc<DateTimeOffset.UtcNow)} workforce tasks are overdue.","workforce"));if(allocations.Exists(x=>x.AcknowledgedAtUtc is null))alerts.Add(new("warning","Supply delivery",$"{allocations.Count(x=>x.AcknowledgedAtUtc is null)} allocations await acknowledgement.","inventory"));if(expenses.Count>0&&expenses.Sum(x=>x.Amount)>lines.Sum(x=>x.AllocatedAmount)*.9m)alerts.Add(new("warning","Budget pressure","Committed expenses exceed 90% of allocation.","finance"));cards.Add(new(e.Id,e.Name,e.ElectionDate,e.LifecycleStateId,teamCount,tasks.Count,centers.Count,centers.Count(x=>x.IsVerified),allocations.Count,allocations.Count(x=>x.AcknowledgedAtUtc is not null),lines.Sum(x=>x.AllocatedAmount),expenses.Sum(x=>x.Amount),eventRows.Count,eventRows.Count(x=>x.StartsAtUtc>=DateTimeOffset.UtcNow),submissions.Count,submissions.Count(x=>verifiedIds.Contains(x.StateId)),alerts));}return new(cards.Count,cards.Count(x=>x.ElectionDate>=today),cards.Sum(x=>x.OpenTaskCount),cards.Sum(x=>x.Alerts.Count),cards);}}
public sealed record OperationsDashboard(int ElectionCount,int ActiveElectionCount,int OpenTaskCount,int AlertCount,IReadOnlyList<ElectionOperationsCard> Elections);public sealed record ElectionOperationsCard(Guid ElectionId,string Name,DateOnly ElectionDate,short LifecycleStateId,int TeamCount,int OpenTaskCount,int CenterCount,int VerifiedCenterCount,int AllocationCount,int AcknowledgedAllocationCount,decimal BudgetAllocated,decimal ExpenseCommitted,int EventCount,int UpcomingEventCount,int ResultSubmissionCount,int VerifiedResultCount,IReadOnlyList<DashboardAlert> Alerts);public sealed record DashboardAlert(string Severity,string Title,string Message,string Route);
